
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_b97_3_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_b97_3", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.214928489000794e+00, -3.153867843747787e+00, -3.068353536142259e+00, -2.950008195338077e+00, -2.789034841294322e+00, -2.575545521712027e+00, -2.302772520511745e+00, -1.973020388801828e+00, -1.604350390613336e+00, -1.220537062983909e+00, -8.280881477904841e-01, -5.572412178315466e-01, -4.849331224322983e-01, -3.980598685145448e-01, -2.912417934578522e-01, -1.819309954262983e-01, -1.052238547969243e-01, -9.127527736698460e-02, -2.516337075607347e-02, -2.961424561380743e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


